@rendermode InteractiveServer
@using sv_ab6a79cefb7d47a995c5dceccfb23495.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 text-light small">Current Warehouse:</label>
    <select class="form-select form-select-sm" @onchange="OnWarehouseChanged" value="@WarehouseState.CurrentWarehouseId">
        @foreach (var wh in WarehouseStateService.Warehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        WarehouseState.CurrentWarehouseId = e.Value?.ToString() ?? "WH-001";
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

